import { useEffect, useState } from 'react';
import { View, Pressable, ScrollView , Alert } from 'react-native';

import _ from 'lodash';

import { 
  COLORS, 
  Status, 
  ButtonIcon, 
  FormRow, 
  InputRow, 
  HRule, 
  Select, 
  CancelAccept, 
  Button, 
  Text, 
  Switch, 
  Icon, 
  Screen, 
  Title 
} from './Basics';

import { WebhooksList } from './Lists';

import { useStore } from '../phone/store';
import { isWeb } from '../utils';

const SelectDevice = ({ devices, deviceId, onChange }) => (
  <Select
    tabIndex="-1"
    options={devices.map(({ deviceId, label }) => {
      return { value: deviceId, text: label };
    })}
    value={deviceId}
    onChange={onChange}
  />
)

const StatusText = ({ text, color } = {}) => (
  <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center' }}>
    <View style={{ paddingLeft: 10, paddingRight: 10 }} >
      <Status color={color} />
    </View>
    <Text>{text}</Text>
  </View>
)

export const StatusForm = ( { style, onChange, ...initialValues }) => {
  const [values, setValues] = useState(initialValues);

  const setValue = (field, value) => {
    const val = { ...values };
    val[field] = value;

    setValues(val);
    onChange?.(val);
  };

  useEffect(() => {
    if (!_.isEqual(initialValues, values)) setValues(initialValues);
  }, [initialValues]);

  const { statuses = [], status } = values;

  if (!statuses.length) return null;

  return (
    <View style={style}>
      <FormRow label={'Status'}>
        <Select
          options={statuses}
          value={status}
          renderCustomizedButtonChild={(item) => {
            const status = statuses.find(status => status.value === item?.value)
            return <StatusText { ...status }/>
          }}
          renderCustomizedRowChild={(_, idx) => <StatusText { ...statuses[idx] } />}
          onChange={val => setValue('status', val)}
        />
      </FormRow>
    </View>
  );
};

export const UserPassForm = (initialValues) => {
  const { loginManaged } = useStore();  
  const [values, setValues] = useState({ ...initialValues });

  const setValue = (field, value) => {
    const val = { ...values };
    val[field] = value;

    setValues(val);
  };

  useEffect(() => {
    if (!_.isEqual(initialValues, values)) setValues(initialValues);
  }, [initialValues]);

  const {
    nickname = '',
    password = '',
  } = values;

  return (
    <View>
      <InputRow
        data-test="user"
        label={'User'}
        placeholder="JohnDoe"
        value={nickname}
        onChange={val => setValue('nickname', val)}
      />

      <InputRow
        data-test="password"
        label={'Password'}
        placeholder="********"
        value={password}
        secureTextEntry
        onChange={val => setValue('password', val)}
      />

      <CancelAccept
        onCancel={() => setValues(initialValues)}
        onAccept={async () => {
          try {
            await loginManaged(values);

            const message = 'Login Successful';
            if (isWeb) {
              alert(message);
            } else {
              Alert.alert('Success', message);
            }
          } catch(err) {
            const message = 'Login Failed';
            if (isWeb) {
              alert(message);
            } else {
              Alert.alert('Failed', message);
            }

            console.error(err);
          }
        }}
        acceptTestID="settingsAccept"
      />
    </View>
  );
};

export const ConnectionForm = ({ onChange, ...initialValues }) => {
  const [values, setValues] = useState(initialValues);
  const [isAuthEnabled, setIsAuthEnabled] = useState(false);

  const setValue = (field, value) => {
    const val = { ...values };
    val[field] = value;

    setValues(val);
    onChange?.(val);
  };

  const {
    settingsUri = '',
    authToken
  } = values;

  return (
    <View>
      <InputRow
        data-test="settingsUri"
        label={'Settings uri'}
        placeholder="https://example.com/settings"
        value={settingsUri}
        onChange={val => setValue('settingsUri', val)}
      />

      <View>
        <Pressable
          style={{ paddingVertical: 10, flexDirection: 'row', alignItems: 'center' }}
          onPress={() => setIsAuthEnabled(!isAuthEnabled)}
        >
          <Text style={{ fontSize: 12 }}>Authentication</Text>

          {isAuthEnabled ? < Icon icon="chevron-down" /> : <Icon icon="chevron-right" /> }
        </Pressable>
          
        {isAuthEnabled && (
          <InputRow
            placeholder="Basic | Bearer token"
            value={authToken}
            onChange={val => setValue('authToken', val)}
          />
        )}
      </View>
    </View>
  );
};

export const DevicesForm = ({ style, onChange, ...initialValues }) => {
  const [values, setValues] = useState(initialValues);

  const setValue = (field, value) => {
    const val = { ...values };
    val[field] = value;

    setValues(val);
    onChange?.(val);
  };

  useEffect(() => {
    if (!_.isEqual(initialValues, values)) setValues(initialValues);
  }, [initialValues]);

  const { devices = [], microphones = [], ringer, microphone, speaker } = values;

  if (!isWeb) return null;

  return (
    <View style={style}>
      <FormRow label={'Speakers'}>
        <SelectDevice devices={devices} deviceId={speaker} onChange={(val) => setValue('speaker', val)} />
      </FormRow>

      <FormRow label={'Microphone'}>
        <SelectDevice devices={microphones} deviceId={microphone} onChange={(val) => setValue('microphone', val)} />
      </FormRow>

      <FormRow label={'Ringer'}>
        <SelectDevice devices={devices} deviceId={ringer} onChange={(val) => setValue('ringer', val)} />
      </FormRow>
    </View>
  );
};

export const DangerZone = ({ style }) => {
  const { clear } = useStore();

  const handleClear = () => {
    const message = 'Are you sure you want to clear all data?'

    if (isWeb) {
      if (confirm(message)) 
        clear();
      
    } else {
      Alert.alert('Clear All', message, [
        {
          text: 'Cancel',
          style: 'cancel',
        },
        {
          text: 'OK', 
          onPress: clear
        },
      ]);
    }
  }

  return (
    <View style={ style }>
      <Title style={{ fontSize: 14, color: 'red' }}>Danger Zone</Title>
      <Button 
        color='danger' 
        onClick={handleClear}
      >
        <Text style={{ color: 'white' }}>Clear all</Text>
      </Button>
    </View>
  )
}

export const QView = () => {
  const store = useStore();

  const {
    qTts,
    qSummarization,
    webhooks,
    events,

    setState,
  } = store;

  return (
    <View style={{ flex: 1 }}>
      <Title>Events</Title>

      {isWeb &&
        <View>
          <View style={{ flexDirection: 'row',  justifyContent: 'space-between', padding: 5 }}>
            <Text>Transcribe</Text>
            <Switch value={qTts} onValueChange={() => {
              const value = !qTts;
              value ? setState({ qTts: value }) : setState({ qTts: false, qSummarization: false })
            }} />
          </View>

          <View style={{ flexDirection: 'row',  justifyContent: 'space-between', padding: 5 }}>
            <Text>Summarize</Text>
            <Switch value={qSummarization} onValueChange={() => setState({ qSummarization: !qSummarization })} />
          </View>

          <HRule />
        </View>
      }

      <View style={{ flex: 1, paddingVertical: 5 }}>
        <Title style={{ fontSize: 12 }}>Webhooks</Title>
        <WebhooksList data={webhooks} />
      </View>
    </View>
  )
}

export const SettingsScreen = ({ visible = false, closeable = true, onClose }) => {
  const store = useStore();
  
  const {
    anchored,
    electron,

    setState,
  } = store;

  const [option, setOption] = useState('settings');

  const onChangeSettingsHandler = input => {
    setState(input);
  };

  
  const UserForm = () => {
    const store = useStore();
  
    const {
      settingsUri,
      authToken,
      login,
    } = store;
    
    const [connection, setConnection] = useState({
      settingsUri,
      authToken
    });

    useEffect(() => {
      setConnection({ settingsUri, authToken });
    }, [settingsUri, authToken]);
  
    const onChangeConnectionHandler = input => {
      setConnection(input);
    };

    
    return (
      <View style={{ flex: 1 }}>
       
        {isWeb &&
        <ScrollView style={{ flexGrow: 1 }}>
           <Title>User</Title>
          <ConnectionForm 
            {...connection}
            onChange={onChangeConnectionHandler}
          />

          <View style={{ marginTop: 10 }}>
            <CancelAccept
              onCancel={() => setConnection({ settingsUri, authToken })}
              onAccept={async () => {
                try {
                 await login(connection);

                  const message = 'Login Successful';
                  if (isWeb) {
                    alert(message);
                  } else {
                    Alert.alert('Success', message);
                  }
                } catch(err) {
                  const message = 'Login Failed';
                  if (isWeb) {
                    alert(message);
                  } else {
                    Alert.alert('Failed', message);
                  }

                  console.error(err);
                }
              }}
              acceptTestID="settingsAccept"
            />
          </View>
        </ScrollView>
        }

        {!isWeb &&
          <ScrollView style={{ flexGrow: 1 }}>
             <Title>Login</Title>
             <UserPassForm {...store} />
          </ScrollView>
        }
        
        <HRule />
        <DangerZone style={{ paddingVertical: 10 }} />
      </View>
    )
  }

  const content = {
    settings: (
      <View style={{ flex: 1 }}>
        <ScrollView style={{ flexGrow: 1 }}>
          <View style={{ flex: 1 }}>
            <StatusForm {...store} onChange={onChangeSettingsHandler} />
            {isWeb &&
              <View>
                <HRule />
                <DevicesForm {...store} onChange={onChangeSettingsHandler} />
              </View>
            }
          </View>

        </ScrollView>
      </View>
    ),
    events: <QView />,
    user: <UserForm />
  };

  let opts = [
    { option: 'settings', icon: 'settings' },
    { option: 'events', icon: 'share-2' },
    { option: 'user', icon: 'user' },
  ]

  return (
    <Screen
      visible={visible}
      closeable={closeable}
      onClose={onClose}
    >
      <View  style={{ flex: 1, flexDirection: 'row' }}>
        
        <View style={{ justifyContent: 'space-between' }} >
          <View key={option} style={{ flex: 1, backgroundColor: COLORS.backColor }}>
            {opts.map((opt, i) => {
              const selected = option === opt.option 
              return (
                <ButtonIcon
                  key={`opt-${i}a`}
                  style={{ padding: 20, backgroundColor: selected ? COLORS.app : null }}
                  icon={opt.icon}
                  color={selected ? COLORS.primary : undefined}
                  onClick={() => setOption(opt.option)} 
                />
              )})}
          </View>

          {electron &&
            <View style={{ backgroundColor: COLORS.backColor }}>
              <ButtonIcon
                style={{ padding: 20 }}
                icon={anchored ? 'unanchor' : 'anchor'}
                onClick={() => setState({ anchored: !anchored })} 
              />
              <ButtonIcon
                style={{ padding: 20 }}
                icon={'x-circle'}
                onClick={() => setState({ doquit: true })} 
              />
            </View>
          }
        </View>

        <View style={{ flex: 1, margin: 10, marginTop: 30 }}>
          {content[option]}
        </View>
      </View>
    </Screen>
  );
};
