export class Sound {
  constructor({ media, loop = false, device = 'default' } = {}) {
    this.audio = new Audio(`./sounds/${media}.mp3`);
    this.audio.loop = loop;
    this.device = device;
  }

  async play() {
    try {
      await this.audio.setSinkId(this.device);
      await this.audio.play();
      this.playing = true;
    } catch (err) {
      console.error(err);
    }
  }

  async stop(pause) {
    try {
      await this.audio.pause();

      if (!pause)
        this.audio.currentTime = 0;
      this.playing = false;
    } catch (err) {
      console.error(err);
    }
  }

  async setDevice(device) {
    this.device = device;

    if (this.playing) {
      this.stop(true);
      this.play();
    }
  }
}
