import vCard from 'vcf';
import { parsePhoneNumberFromString } from 'libphonenumber-js';

import { cleanPhoneNumber } from '../utils';

const elasticlunr = require('elasticlunr');
const { Level } = require('level');

elasticlunr.clearStopWords();

let CONTACTS_VCF_IDS = [];
let HASH = {};
let IDX;

const NGRAMLEN = 4;
const DBNAME = 'KZCS';

const initIndex = () => {
  CONTACTS_VCF_IDS = [];
  HASH = {};

  IDX = elasticlunr(function () {
    this.setRef('id');
    this.addField('name');
    this.addField('phones');
    this.saveDocument(false);
  });
};

const index = ({ contacts, size = 100, onIndexed } = {}) => {
  if (!contacts?.length) {
    onIndexed?.();
    document?.dispatchEvent(new Event('indexing:end'));
    return;
  }

  const long_tail_tokens = (str, ngramlen = NGRAMLEN, number) => {
    if (!str) return [];

    const tokens = (number ? str.replace(/\s/g, '') : str).split(' ');
    let ngrams = [];

    if (ngramlen > 0) {
      for (let j = 0; j < tokens.length; j++) {
        const token = tokens[j];
        for (let i = 0; i < token.length; i++) {
          ngrams = ngrams.concat(
            token.split('').map((_, idx) => token.substr(i, idx + 1))
          );
        }
      }
    }

    return tokens.concat(ngrams.filter(ngram => ngram.length >= ngramlen));
  };

  let indexed = 0;
  const max = Math.ceil(contacts.length / size);
  for (let i = 0; i < max; i++) {
    document?.dispatchEvent(new Event('indexing'));

    const from = i * size;
    const to = (i + 1) * size;
    const chunk = contacts.slice(from, to);

    // eslint-disable-next-line no-loop-func
    requestIdleCallback(async () => {
      try {
        chunk.forEach(async user => {
          if (user.id.startsWith('cvf-')) CONTACTS_VCF_IDS.push(user.id);

          HASH[user.id] = user;
          IDX.addDoc({
            id: user.id,
            name: long_tail_tokens(user.name, NGRAMLEN),
            phones: [].concat.apply(
              [],
              user.phones.map(number =>
                long_tail_tokens(cleanPhoneNumber(number), NGRAMLEN, true)
              )
            )
          });
        });
      } finally {
        indexed += chunk.length;

        if (indexed === contacts.length) {
          onIndexed?.();
          document?.dispatchEvent(new Event('indexing:end'));
        }
      }
    });
  }
};

export const fromVCF = ({ vcf }) => {
  const cards = vCard.parse(vcf.replace(/\r?\n/g, '\r\n'));

  const cardget = (card, prop, def) => {
    try {
      return card.get(prop).valueOf();
    } catch {}

    return def;
  }

  const contacts = cards
    .map((card, idx) => {
      try {
        const id = `cvf-${idx}`;
        const name = cardget(card, 'fn');
        const avatar = cardget(card, 'photo');
        const url = cardget(card, 'url');

        let phones = cardget(card, 'tel');
        if (Array.isArray(phones)) {
          phones = phones.map(phone => phone.valueOf());
        } else if (phones) {
          phones = [phones.valueOf()];
        }
        
        return { id, name, url, avatar, phones };
      } catch (err) {
        console.error(err);
      }
    })
    .filter(contact => contact !== undefined);

  return contacts;
};

class Contacts {
  constructor() {
    initIndex();

    this.fs = new Level(DBNAME, { valueEncoding: 'json' });
    this.loaded = false;

    this.load();
  }

  async load(id = 'contacts') {
    try {
      const { hash = {}, index } = (await this.fs.get(id)) || {};
      HASH = hash;

      if (index) {
        IDX = elasticlunr.Index.load(index);
        document?.dispatchEvent(new Event('indexing:end'));
      }
    } catch (err) {
      index({ users: [] });
    }

    this.loaded = true;
  }

  async total() {  
    return Object.keys(HASH).length;  
  }

  async query({ query, max } = {}) {
    if (!this.loaded) await this.load();

    const result =
      !query || query.length < NGRAMLEN
        ? Object.values(HASH)
        : IDX.search(query, {}).map(({ score, ref }) => ({
            score,
            ...HASH[ref]
          }));

    const hits = result
      .slice(0, max || result.length)
      .filter(item => item.id !== undefined)
      .sort((a, b) => {
        if (a.score === b.score) return a.vcf ? 1 : -1;

        return b.score - a.score;
      });

    return { hits, total: result.length };
  }

  async contactByPhone({ phone = '' }) {
    const cleanNumber = (number) => 
      parsePhoneNumberFromString(number, 'US')?.nationalNumber || phone;
    
    const query = cleanPhoneNumber(phone);
    const { hits = [] } = await this.query({ query });

    return hits.find(contact => contact.phones.some(number => cleanNumber(number) === cleanNumber(phone)));
  }

  async save(id = 'contacts') {
    await this.fs.put(id, { hash: HASH, index: IDX.toJSON() });
  }

  async index({ vcf, contacts = [] }) {
    if (vcf) {
      CONTACTS_VCF_IDS.forEach(id => {
        IDX.removeDoc(HASH[id]);
        delete HASH[id];
      });
      CONTACTS_VCF_IDS = [];

      const contacts = fromVCF({ vcf })
        .filter(contact => contact?.phones?.length)
        .map(contact => ({ ...contact, vcf: true }));

      index({ contacts, onIndexed: () => {
        this.save()
      }
      });
    }

    if (contacts.length) {
      index({ contacts });
    }
  }

  async clear() {
    initIndex();
    this.fs.clear();
  }
}

const contacts = new Contacts();
export default contacts;
